            aOrbiterC = (aWandererC + RotL64(aIngress, 35U)) + 0xA0992F308A730EE1ULL;
            aOrbiterK = (aWandererA + RotL64(aPrevious, 53U)) + 0x1C0F9DBA6F30F2DDULL;
            aOrbiterJ = ((aWandererH + RotL64(aScatter, 57U)) + RotL64(aCarry, 13U)) + 0x12F073A42EF4AF0AULL;
            aOrbiterA = ((aWandererJ + RotL64(aIngress, 10U)) + 0xBC12E596F1838AECULL) + aTwistOrbiterAssignSaltD[((aIndex + 9U)) & S_SALT1];
            aOrbiterF = (aWandererG + RotL64(aPrevious, 47U)) + 0xD9A323666EB49BBBULL;
            aOrbiterE = ((aWandererD + RotL64(aScatter, 19U)) + 0x0BD7E13C82913882ULL) + aTwistOrbiterAssignSaltB[(((31U - aIndex) + 19U)) & S_SALT1];
            aOrbiterG = ((aWandererB + RotL64(aCross, 39U)) + RotL64(aCarry, 23U)) + 0x4BAE0D4643DE5688ULL;
            aOrbiterB = ((aWandererF + RotL64(aIngress, 23U)) + RotL64(aCarry, 39U)) + 0x0559ED5E82A8E977ULL;
            //
