            //
            aOrbiterK = (aWandererG + RotL64(aCross, 37U)) + 0x26F551028445EBEBULL;
            aOrbiterG = (aWandererF + RotL64(aPrevious, 5U)) + 0x778A617C2396040AULL;
            aOrbiterE = (((aWandererD + RotL64(aScatter, 21U)) + RotL64(aCarry, 37U)) + 0x1AD59220F1F9BF1AULL) + aTwistOrbiterAssignSaltF[((aIndex + 23U)) & S_SALT1];
            aOrbiterI = ((aWandererC + RotL64(aIngress, 51U)) + RotL64(aCarry, 21U)) + 0x89B32D06E460C709ULL;
            aOrbiterJ = ((aWandererB + RotL64(aCross, 11U)) + RotL64(aCarry, 57U)) + 0xB85E6814419214A3ULL;
            aOrbiterH = (aWandererI + RotL64(aScatter, 43U)) + 0xC3E1DC093C70B3F7ULL;
            aOrbiterF = ((aWandererE + RotL64(aPrevious, 60U)) + 0x82297B0A1467BB99ULL) + aTwistOrbiterAssignSaltA[(((31U - aIndex) + 7U)) & S_SALT1];
            //
            aOrbiterK = ((aOrbiterK + aOrbiterG) + 0x60739298F8A6B6BDULL) + aTwistOrbiterUpdateSaltD[(((31U - aIndex) + 28U)) & S_SALT1];
