            //
            aOrbiterI = (aOrbiterI + aOrbiterK) + 0xC0E88675ECFC6E42ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterI) ^ 0x58C54B5C96BBD666ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x4737184BE0DE8785ULL), 29U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterH) + 0x1C3979F658082B1FULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterJ) ^ 0x1A4533E44D7CCE37ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x6ADD483C50583573ULL), 13U);
            //
            aIngress = aOrbiterG ^ RotL64(aOrbiterE, 51U);
            aIngress = aIngress + (aOrbiterJ ^ RotL64(aOrbiterI, 57U));
            aIngress = aIngress + (RotL64(aOrbiterK, 21U) ^ aOrbiterF);
            aIngress = aIngress + RotL64(aOrbiterH, 4U);
            aIngress = TwistMix64::DiffuseB((aIngress + aScatter));
            //
            aWandererB = aWandererB + ((RotL64(aCross, 19U) + aOrbiterE) + RotL64(aOrbiterI, 53U));
            aWandererG = aWandererG ^ ((RotL64(aIngress, 57U) + aOrbiterG) + RotL64(aOrbiterI, 21U));
            aWandererE = aWandererE + ((RotL64(aPrevious, 41U) + aOrbiterK) + RotL64(aOrbiterF, 27U));
            aWandererC = aWandererC ^ ((RotL64(aScatter, 4U) + aOrbiterJ) + RotL64(aOrbiterF, 34U));
            aWandererI = aWandererI + (((RotL64(aPrevious, 51U) + RotL64(aOrbiterJ, 5U)) + aOrbiterH) + RotL64(aCarry, 3U));
            aWandererF = aWandererF ^ (((RotL64(aIngress, 29U) + aOrbiterH) + RotL64(aOrbiterF, 11U)) + aTwistWandererUpdateSaltE[(((31U - aIndex) + 14U)) & S_SALT1]);
            aWandererD = aWandererD + ((((RotL64(aCross, 13U) + aOrbiterK) + RotL64(aOrbiterG, 41U)) + RotL64(aCarry, 51U)) + aTwistWandererUpdateSaltC[(((31U - aIndex) + 29U)) & S_SALT1]);
