        //      aFuseLaneA (-->), aWaterLaneC (-->), pCrossLaneC (-->), aEarthLaneD (<-?->)
        //
        // Cross:
        //      aWaterLaneA (<--), aWaterLaneD (<--), aEarthLaneA (<--), pCrossLaneD (<-?->)
        //
        // Destination:
        //      aFuseLaneB
