            aCross ^= (RotL64(aEarthLaneA[((S_BLOCK1 - aIndex + 10979U)) & S_BLOCK1], 57U) ^ RotL64(pCrossLaneD[((S_BLOCK1 - aIndex + 11149U)) & S_BLOCK1], 28U));
            aCross = TwistMix64::DiffuseB((aCross ^ aTwistDomainWordCross));
            //
            aScatter = (RotL64(aCarry, 41U) + RotL64(aPrevious, 11U)) + (RotL64(aCross, 56U) ^ RotL64(aIngress, 29U));
            aScatter = TwistMix64::DiffuseA((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterG = ((aWandererJ + RotL64(aIngress, 39U)) + RotL64(aCarry, 37U)) + 0x7C985670F741EFE6ULL;
            aOrbiterD = ((aWandererG + RotL64(aPrevious, 3U)) + 0x6D20DFC34677889FULL) + aTwistOrbiterAssignSaltC[((aIndex + 18U)) & S_SALT1];
            aOrbiterB = ((aWandererK + RotL64(aScatter, 21U)) + RotL64(aCarry, 13U)) + 0x95E3A25C4AF4BF07ULL;
            aOrbiterA = (aWandererI + RotL64(aCross, 50U)) + 0xCC41A057DE53F91EULL;
            aOrbiterJ = (aWandererF + RotL64(aScatter, 13U)) + 0x37F317D90B2C370AULL;
            aOrbiterE = ((aWandererC + RotL64(aCross, 57U)) + RotL64(aCarry, 51U)) + 0x6DB09BE06EF97E53ULL;
            aOrbiterK = ((aWandererE + RotL64(aPrevious, 29U)) + 0x89C51396B011639BULL) + aTwistOrbiterAssignSaltB[(((31U - aIndex) + 11U)) & S_SALT1];
            //
            aOrbiterG = (aOrbiterG + aOrbiterD) + 0x10238BD9EED9AB1AULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterG) ^ 0xBF1638C8324BA08BULL;
            aOrbiterB = RotL64((aOrbiterB * 0x838A21DEA08BF13FULL), 41U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterJ) + 0x3BA4A95FC86A8A05ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterA) ^ 0x65B8EBF5C9CED0B7ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x7D6D9DE4358541D9ULL), 57U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterE) + 0x5B887B488F1E485EULL) + aTwistOrbiterUpdateSaltD[((aIndex + 21U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterD) ^ 0xD4940D948F3465FBULL;
            aOrbiterK = RotL64((aOrbiterK * 0x5BF683AA073679C9ULL), 13U);
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterG) + 0x21D4C10176B87E4BULL) + aTwistOrbiterUpdateSaltB[((aIndex + 4U)) & S_SALT1];
            aOrbiterE = ((aOrbiterE ^ aOrbiterJ) ^ 0x1A2DF5230E5168A7ULL) ^ aTwistOrbiterUpdateSaltC[(((31U - aIndex) + 3U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0xE8324D628F6378A9ULL), 35U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterB) + 0xF02F5412748C2F85ULL) + aTwistOrbiterUpdateSaltA[((aIndex + 12U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterE) ^ 0xE8A5D2B531E99E42ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x1BE1724CBAAF3E3BULL), 23U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterA) + 0x833597BD15DC197BULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterK) ^ 0xAA36F11053308BE8ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x8632C8B0648DF245ULL), 47U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterK) + 0x8858AAA39AADC45EULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterB) ^ 0x68628F155B594827ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x34A825326B5B29C1ULL), 5U);
