            aIngress = aOrbiterA ^ RotL64(aOrbiterD, 21U);
            aIngress = aIngress + (aOrbiterB ^ RotL64(aOrbiterJ, 47U));
            aIngress = aIngress + (aOrbiterK ^ RotL64(aOrbiterG, 5U));
            aIngress = aIngress + RotL64(aOrbiterE, 39U);
            aIngress = TwistMix64::DiffuseC((aIngress + aScatter));
            //
            aWandererC = aWandererC ^ ((RotL64(aScatter, 21U) + RotL64(aOrbiterJ, 5U)) + aOrbiterG);
            aWandererI = aWandererI + (((RotL64(aPrevious, 47U) + RotL64(aOrbiterA, 44U)) + aOrbiterG) + RotL64(aCarry, 43U));
            aWandererG = aWandererG ^ ((RotL64(aIngress, 37U) + RotL64(aOrbiterA, 35U)) + aOrbiterD);
            aWandererK = aWandererK + (((RotL64(aCross, 30U) + aOrbiterG) + RotL64(aOrbiterB, 29U)) + aTwistWandererUpdateSaltD[((aIndex + 25U)) & S_SALT1]);
