            aWandererF = aWandererF ^ (((RotL64(aPrevious, 13U) + RotL64(aOrbiterK, 23U)) + aOrbiterD) + aTwistWandererUpdateSaltB[((aIndex + 5U)) & S_SALT1]);
            //
            aCarry = aCarry + (aWandererI ^ RotL64(aWandererF, 4U));
