            aCross = (RotL64(aFuseLaneB[((S_BLOCK1 - aIndex + 28519U)) & S_BLOCK1], 4U) ^ RotL64(aIceLaneC[((S_BLOCK1 - aIndex + 25365U)) & S_BLOCK1], 47U));
