            aOrbiterE = (aWandererG + RotL64(aScatter, 19U)) + 0x892E668B74354DB2ULL;
            aOrbiterD = ((aWandererI + RotL64(aPrevious, 41U)) + 0xD440BED4341CBDEFULL) + aTwistOrbiterAssignSaltD[((aIndex + 16U)) & S_SALT1];
            aOrbiterH = (aWandererK + RotL64(aCross, 56U)) + 0x59701BADE144120FULL;
