            //
            aOrbiterK = (aOrbiterK + aOrbiterB) + 0xAC49AF64E64CD570ULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterK) ^ 0x71F7D653ED5B5A13ULL) ^ aTwistOrbiterUpdateSaltF[(((31U - aIndex) + 25U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0x5A58D6ECE950CA21ULL), 27U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterD) + 0xCF037F7DD780DD56ULL;
