            aOrbiterB = ((aWandererI + RotL64(aIngress, 34U)) + 0xB086F7E7D56E1F9EULL) + aTwistOrbiterAssignSaltC[((aIndex + 28U)) & S_SALT1];
            aOrbiterJ = (aWandererF + RotL64(aCross, 5U)) + 0xD234E27C1D99CE93ULL;
            aOrbiterK = (aWandererB + RotL64(aScatter, 57U)) + 0xC97EA509311EBC89ULL;
            aOrbiterA = (aWandererJ + RotL64(aPrevious, 23U)) + 0x7F1FAEB64DC54BBFULL;
            aOrbiterD = ((aWandererG + RotL64(aCross, 43U)) + RotL64(aCarry, 11U)) + 0xCE7F2289FDFC550DULL;
            aOrbiterH = ((aWandererD + RotL64(aIngress, 29U)) + RotL64(aCarry, 47U)) + 0xBEA427BAEE70D230ULL;
            aOrbiterI = (aWandererH + RotL64(aPrevious, 39U)) + 0x603632A991902AC0ULL;
            aOrbiterC = (((aWandererE + RotL64(aScatter, 48U)) + RotL64(aCarry, 3U)) + 0x844571071B2A869DULL) + aTwistOrbiterAssignSaltA[(((31U - aIndex) + 21U)) & S_SALT1];
            aOrbiterF = (aWandererA + RotL64(aCross, 13U)) + 0xDDCEBDD172C9965EULL;
            //
            aOrbiterB = ((aOrbiterB + aOrbiterJ) + 0x085AFCB63924098DULL) + aTwistOrbiterUpdateSaltF[((aIndex + 6U)) & S_SALT1];
            aOrbiterK = ((aOrbiterK ^ aOrbiterB) ^ 0x28914C10161C8AE6ULL) ^ aTwistOrbiterUpdateSaltE[(((31U - aIndex) + 19U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0xE2B11598B6687557ULL), 37U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterD) + 0x5AC7280D96DB0CC3ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterA) ^ 0x40A206E7C973727FULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x0128081D7643F289ULL), 3U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterA) + 0xBAD2FAE50549BB01ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterH) ^ 0x19AD0C488C23EAEBULL;
            aOrbiterB = RotL64((aOrbiterB * 0x189F5DA2D555C1EFULL), 23U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterC) + 0xEF917BF0A5F105C1ULL) + aTwistOrbiterUpdateSaltC[(((31U - aIndex) + 4U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterI) ^ 0x71BB3CA2039AE813ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x57E19186DCDFB12BULL), 41U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterF) + 0x9D271498E1C40D20ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterJ) ^ 0xF518CC5B2D8EE024ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x12025F4BECB2283DULL), 57U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterH) + 0x2EA09A02634A20C1ULL) + aTwistOrbiterUpdateSaltB[((aIndex + 24U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterD) ^ 0x207DEA9D84D232DDULL;
            aOrbiterF = RotL64((aOrbiterF * 0x4868F99ED6FB3037ULL), 29U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterI) + 0x152782EA1CFEC0BCULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterK) ^ 0xB029DA2AB9DD3CB2ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x74F65C62BB5617BFULL), 11U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterB) + 0x36D184DAA8428454ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterF) ^ 0xD0B9D0BBC207B6C8ULL;
            aOrbiterC = RotL64((aOrbiterC * 0xE6168B2B5A3E8275ULL), 53U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterK) + 0x9E6A5655B2CA2A2DULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterC) ^ 0x2FEF681B10D4C8F4ULL;
