            aIngress = aIngress + (aOrbiterA ^ RotL64(aOrbiterD, 6U));
            aIngress = aIngress + (RotL64(aOrbiterC, 13U) ^ aOrbiterB);
            aIngress = aIngress + RotL64(aOrbiterK, 37U);
