            //
            aWandererG = aWandererG ^ ((RotL64(aIngress, 60U) + aOrbiterK) + RotL64(aOrbiterI, 21U));
            aWandererI = aWandererI + ((((RotL64(aPrevious, 3U) + RotL64(aOrbiterK, 39U)) + aOrbiterH) + RotL64(aCarry, 53U)) + aTwistWandererUpdateSaltB[((aIndex + 5U)) & S_SALT1]);
            aWandererJ = aWandererJ ^ (((RotL64(aCross, 21U) + aOrbiterA) + RotL64(aOrbiterI, 60U)) + aTwistWandererUpdateSaltF[(((31U - aIndex) + 15U)) & S_SALT1]);
            aWandererB = aWandererB + ((RotL64(aScatter, 43U) + aOrbiterD) + RotL64(aOrbiterH, 47U));
