            aWandererA = aWandererA + ((RotL64(aPrevious, 34U) + RotL64(aOrbiterC, 3U)) + aOrbiterD);
            aWandererH = aWandererH ^ ((RotL64(aIngress, 53U) + RotL64(aOrbiterJ, 54U)) + aOrbiterH);
            aWandererD = aWandererD + (((RotL64(aScatter, 47U) + aOrbiterF) + RotL64(aOrbiterJ, 43U)) + RotL64(aCarry, 5U));
            aWandererE = aWandererE ^ ((RotL64(aCross, 11U) + RotL64(aOrbiterF, 35U)) + aOrbiterB);
