            aOrbiterH = ((aOrbiterH + aOrbiterD) + 0x42A465BC4B93565FULL) + aKeyRotateAOrbiterUpdateSaltB[((aIndex + 24U)) & S_SALT1];
            aOrbiterA = ((aOrbiterA ^ aOrbiterH) ^ 0x4D21CAE2545CC988ULL) ^ aKeyRotateAOrbiterUpdateSaltA[(((31U - aIndex) + 19U)) & S_SALT1];
