            aWandererD = aWandererD ^ ((RotL64(aScatter, 39U) + aOrbiterF) + RotL64(aOrbiterE, 23U));
            aWandererA = aWandererA + (((RotL64(aIngress, 47U) + RotL64(aOrbiterF, 57U)) + aOrbiterH) + aKeyRotateAWandererUpdateSaltF[((aIndex + 25U)) & S_SALT1]);
            aWandererC = aWandererC ^ ((RotL64(aScatter, 21U) + RotL64(aOrbiterC, 14U)) + aOrbiterK);
