            aOrbiterB = ((aWandererJ + RotL64(aCross, 19U)) + RotL64(aCarry, 21U)) + 0xE89F67D65F8665F5ULL;
            aOrbiterC = ((aWandererD + RotL64(aPrevious, 41U)) + RotL64(aCarry, 5U)) + 0xF3C2C0AEA09F757DULL;
            aOrbiterE = (((aWandererC + RotL64(aIngress, 43U)) + RotL64(aCarry, 29U)) + 0x928F23B7AE071DF1ULL) + aKeyRotateAOrbiterAssignSaltF[(((31U - aIndex) + 28U)) & S_SALT1];
            aOrbiterD = (aWandererA + RotL64(aScatter, 23U)) + 0x76D82F01E7385026ULL;
            aOrbiterH = (aWandererK + RotL64(aCross, 28U)) + 0xA750417241CB1B46ULL;
            aOrbiterA = (aWandererF + RotL64(aScatter, 5U)) + 0x637D244F18D277A1ULL;
            aOrbiterF = (aWandererG + RotL64(aPrevious, 13U)) + 0x20A86BE40C4336D5ULL;
