            aOrbiterK = RotL64((aOrbiterK * 0x735763A28404EEE1ULL), 51U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterA) + 0x7750C6B1E4910CF2ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterB) ^ 0x58E06BAF16F88B4AULL;
            aOrbiterC = RotL64((aOrbiterC * 0x59B8E927477810C5ULL), 29U);
            //
            aOrbiterC = ((aOrbiterC + aOrbiterD) + 0x3A086511306B0178ULL) + aKeyRotateAOrbiterUpdateSaltB[(((31U - aIndex) + 3U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterC) ^ 0xDFB51C733828C55DULL;
            aOrbiterI = RotL64((aOrbiterI * 0x3C37D6FB8839B577ULL), 37U);
            //
            aIngress = RotL64(aOrbiterF, 41U) ^ aOrbiterH;
