            aIngress = aIngress + (aOrbiterJ ^ RotL64(aOrbiterD, 34U));
            aIngress = aIngress + (RotL64(aOrbiterI, 57U) ^ aOrbiterB);
            aIngress = aIngress + (RotL64(aOrbiterK, 11U) ^ aOrbiterC);
            aIngress = aIngress + RotL64(aOrbiterG, 27U);
            aIngress = TwistMix64::DiffuseC((aIngress + aScatter));
            //
            aWandererB = aWandererB ^ ((RotL64(aIngress, 14U) + aOrbiterJ) + RotL64(aOrbiterD, 47U));
            aWandererJ = aWandererJ + ((((RotL64(aCross, 29U) + RotL64(aOrbiterJ, 54U)) + aOrbiterG) + RotL64(aCarry, 11U)) + aKeyRotateAWandererUpdateSaltE[((aIndex + 24U)) & S_SALT1]);
