            aScatter = TwistMix64::DiffuseA((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterI = (aWandererC + RotL64(aIngress, 6U)) + 0xF41633B34C90D427ULL;
            aOrbiterC = (((aWandererK + RotL64(aScatter, 51U)) + RotL64(aCarry, 51U)) + 0xBC8E21A4B3D6DF5BULL) + aKeyRotateAOrbiterAssignSaltF[((aIndex + 14U)) & S_SALT1];
            aOrbiterH = (aWandererJ + RotL64(aCross, 57U)) + 0xBCA2D5B2C818D65DULL;
            aOrbiterD = ((aWandererH + RotL64(aPrevious, 29U)) + 0xB1AF2EA4937CBDDDULL) + aKeyRotateAOrbiterAssignSaltA[(((31U - aIndex) + 23U)) & S_SALT1];
            aOrbiterA = ((aWandererB + RotL64(aCross, 37U)) + RotL64(aCarry, 37U)) + 0xC5DAF7C77175AC9EULL;
            aOrbiterJ = (aWandererG + RotL64(aScatter, 13U)) + 0xF6160E137490F271ULL;
            aOrbiterE = ((aWandererA + RotL64(aIngress, 23U)) + RotL64(aCarry, 23U)) + 0x8C72F9D48C671F61ULL;
            //
            aOrbiterI = (aOrbiterI + aOrbiterC) + 0x28EBDE52CE4F2F23ULL;
