            //
            aOrbiterH = ((aOrbiterH + aOrbiterE) + 0x4179E2EB848AC110ULL) + aKeyRotateAOrbiterUpdateSaltC[(((31U - aIndex) + 26U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterH) ^ 0xE73C1E9826060DEFULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x91751C156DC2EE39ULL), 29U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterI) + 0x37D0D1F84441279BULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterE) ^ 0x1AFE39A205D53222ULL;
            aOrbiterD = RotL64((aOrbiterD * 0xC19CABF0D6D54F63ULL), 35U);
            //
            aOrbiterC = ((aOrbiterC + aOrbiterA) + 0xCF9516FB22B9F288ULL) + aKeyRotateAOrbiterUpdateSaltE[(((31U - aIndex) + 25U)) & S_SALT1];
            aOrbiterE = ((aOrbiterE ^ aOrbiterC) ^ 0x47C059A222096755ULL) ^ aKeyRotateAOrbiterUpdateSaltD[((aIndex + 24U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0x9A7875E210A39F8BULL), 57U);
            //
            aIngress = aOrbiterD ^ RotL64(aOrbiterA, 3U);
