            aIngress = aIngress + (aOrbiterI ^ RotL64(aOrbiterH, 29U));
            aIngress = aIngress + RotL64(aOrbiterC, 11U);
            aIngress = TwistMix64::DiffuseB((aIngress + aScatter));
            //
            aWandererG = aWandererG + ((RotL64(aScatter, 3U) + RotL64(aOrbiterC, 60U)) + aOrbiterI);
            aWandererB = aWandererB ^ ((RotL64(aIngress, 37U) + aOrbiterC) + RotL64(aOrbiterA, 53U));
            aWandererA = aWandererA + ((RotL64(aCross, 13U) + aOrbiterE) + RotL64(aOrbiterH, 43U));
            aWandererK = aWandererK ^ ((RotL64(aPrevious, 47U) + RotL64(aOrbiterD, 19U)) + aOrbiterH);
