            aIngress ^= (RotL64(aWaterLaneC[((aIndex + 9397U)) & S_BLOCK1], 57U) ^ RotL64(aWoodLaneD[((S_BLOCK1 - aIndex + 15858U)) & S_BLOCK1], 3U));
            aIngress = TwistMix64::DiffuseB((aIngress ^ aKeyRotateADomainWordIngress));
            //
            aCross = (RotL64(aWindLaneA[((S_BLOCK1 - aIndex + 16233U)) & S_BLOCK1], 57U) ^ RotL64(aWindLaneD[((S_BLOCK1 - aIndex + 10345U)) & S_BLOCK1], 12U));
            aCross ^= (RotL64(aPoisonLaneB[((S_BLOCK1 - aIndex + 15470U)) & S_BLOCK1], 21U) ^ RotL64(aShadowLaneD[((S_BLOCK1 - aIndex + 11733U)) & S_BLOCK1], 3U));
            aCross = TwistMix64::DiffuseA((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aCross, 53U) + RotL64(aIngress, 13U)) ^ (RotL64(aPrevious, 28U) ^ RotL64(aCarry, 41U));
            aScatter = TwistMix64::DiffuseC((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterB = (aWandererE + RotL64(aCross, 37U)) + 0xDA45D3F551539E72ULL;
            aOrbiterK = (aWandererG + RotL64(aIngress, 47U)) + 0x644D3AD0252E922BULL;
            aOrbiterA = ((aWandererB + RotL64(aPrevious, 5U)) + RotL64(aCarry, 57U)) + 0x3D8E293AF3B1FC79ULL;
            aOrbiterC = ((aWandererI + RotL64(aScatter, 60U)) + 0x0D20595C1C3CCCA9ULL) + aKeyRotateAOrbiterAssignSaltD[(((31U - aIndex) + 13U)) & S_SALT1];
            aOrbiterG = ((aWandererK + RotL64(aCross, 53U)) + RotL64(aCarry, 5U)) + 0xFA680E3EDE636FCEULL;
            aOrbiterF = ((aWandererD + RotL64(aIngress, 13U)) + RotL64(aCarry, 39U)) + 0xE64EE58AFD785B61ULL;
            aOrbiterH = ((aWandererC + RotL64(aScatter, 27U)) + 0xB995D7D98A94507AULL) + aKeyRotateAOrbiterAssignSaltB[((aIndex + 12U)) & S_SALT1];
            //
            aOrbiterB = (aOrbiterB + aOrbiterK) + 0x48174C84FA127288ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterB) ^ 0x1D82D85A279E2E5FULL;
            aOrbiterA = RotL64((aOrbiterA * 0x3B6920756F8B7697ULL), 57U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterC) + 0x7746C565C5306F8DULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterA) ^ 0x9F9C77C1127D177DULL;
            aOrbiterG = RotL64((aOrbiterG * 0x98888FD672CE74CBULL), 3U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterA) + 0xA0541BBE3E64977DULL) + aKeyRotateAOrbiterUpdateSaltC[((aIndex + 29U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterF) ^ 0x2022ED377D66BC4CULL;
            aOrbiterH = RotL64((aOrbiterH * 0x0BD49EC4A57B62FBULL), 11U);
            //
            aOrbiterC = ((aOrbiterC + aOrbiterH) + 0xC21A7167C1F7DB08ULL) + aKeyRotateAOrbiterUpdateSaltA[((aIndex + 24U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterC) ^ 0xFEFAFD77DDA1D7A8ULL;
            aOrbiterB = RotL64((aOrbiterB * 0xD5B56D96A94EB7E9ULL), 41U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterF) + 0xEEC455D37EB9EEE5ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterK) ^ 0x5EB25D6982DE3DCFULL;
            aOrbiterC = RotL64((aOrbiterC * 0x4E3626197AA5DDCDULL), 23U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterB) + 0xA87714D39E2F8F5EULL) + aKeyRotateAOrbiterUpdateSaltB[(((31U - aIndex) + 5U)) & S_SALT1];
            aOrbiterF = ((aOrbiterF ^ aOrbiterG) ^ 0x49E2C80C68761812ULL) ^ aKeyRotateAOrbiterUpdateSaltF[(((31U - aIndex) + 25U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0x602E9EBCE5559669ULL), 47U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterG) + 0xE36946FAF08E5B54ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterH) ^ 0xB23736CAE44D6A48ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x929641684AF253F1ULL), 35U);
            //
            aIngress = aOrbiterG ^ RotL64(aOrbiterK, 47U);
            aIngress = aIngress + (RotL64(aOrbiterB, 13U) ^ aOrbiterA);
            aIngress = aIngress + (aOrbiterC ^ RotL64(aOrbiterF, 29U));
            aIngress = aIngress + RotL64(aOrbiterH, 57U);
            aIngress = TwistMix64::DiffuseC((aIngress + aScatter));
