            aWandererC = aWandererC ^ ((RotL64(aPrevious, 21U) + aOrbiterA) + RotL64(aOrbiterG, 3U));
            aWandererE = aWandererE + (((RotL64(aIngress, 57U) + RotL64(aOrbiterB, 35U)) + aOrbiterC) + aKeyRotateAWandererUpdateSaltF[(((31U - aIndex) + 4U)) & S_SALT1]);
            aWandererG = aWandererG ^ ((RotL64(aScatter, 41U) + RotL64(aOrbiterH, 27U)) + aOrbiterF);
            aWandererI = aWandererI + (((RotL64(aCross, 3U) + RotL64(aOrbiterA, 19U)) + aOrbiterC) + RotL64(aCarry, 37U));
