            aCross = TwistMix64::DiffuseA((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aIngress, 57U) ^ RotL64(aCarry, 42U)) + (RotL64(aCross, 5U) + RotL64(aPrevious, 21U));
