            //
            aOrbiterE = ((aWandererB + RotL64(aScatter, 21U)) + RotL64(aCarry, 19U)) + 0x3D2D35ECA74198C6ULL;
            aOrbiterI = ((aWandererF + RotL64(aCross, 51U)) + RotL64(aCarry, 41U)) + 0x8F40504AF5DCED1BULL;
            aOrbiterG = ((aWandererC + RotL64(aPrevious, 3U)) + 0xD5EB748F51B8EFC1ULL) + aKeyRotateAOrbiterAssignSaltE[((aIndex + 13U)) & S_SALT1];
            aOrbiterC = (aWandererJ + RotL64(aIngress, 44U)) + 0x4F3C6FAEA42220ACULL;
            aOrbiterD = (aWandererA + RotL64(aPrevious, 13U)) + 0x4DA322F1D51F1306ULL;
            aOrbiterJ = (((aWandererI + RotL64(aIngress, 57U)) + RotL64(aCarry, 57U)) + 0x7F3B047E3B6F077CULL) + aKeyRotateAOrbiterAssignSaltC[(((31U - aIndex) + 25U)) & S_SALT1];
            aOrbiterB = (aWandererK + RotL64(aCross, 27U)) + 0x12A829481B83DA4EULL;
            //
            aOrbiterE = (aOrbiterE + aOrbiterI) + 0x6D2F76E0923C2E1DULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterE) ^ 0xE7B8E1B4254491DBULL;
            aOrbiterG = RotL64((aOrbiterG * 0x060E08BF0AF442A1ULL), 39U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterD) + 0xD22D6992AB53E27CULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterC) ^ 0x292BC8929DCF131CULL;
            aOrbiterE = RotL64((aOrbiterE * 0x148CF83C6EF8088FULL), 27U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterJ) + 0x10A5E9E86D3B365BULL;
