            aOrbiterB = RotL64((aOrbiterB * 0xDFABF8727F74960DULL), 21U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterC) + 0xA0FCE399A057E2A0ULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterB) ^ 0xE27E331F4DA65B47ULL) ^ aKeyRotateAOrbiterUpdateSaltF[((aIndex + 22U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0x94A520AA64290215ULL), 11U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterE) + 0x7690D76373237D7FULL) + aKeyRotateAOrbiterUpdateSaltC[((aIndex + 7U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterD) ^ 0x0D92B4378EE19704ULL;
