            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterB) + 0x308391D20B183DDEULL) + aKeyRotateAOrbiterUpdateSaltB[(((31U - aIndex) + 3U)) & S_SALT1];
            aOrbiterC = ((aOrbiterC ^ aOrbiterJ) ^ 0xFA57E154F6D81225ULL) ^ aKeyRotateAOrbiterUpdateSaltD[((aIndex + 4U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0xC7718A5FBE56744FULL), 47U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterG) + 0x9D8EE9AD9BBDAA4DULL;
