        //
        // Ingress:
        //      aFuseLaneC (-->), aFuseLaneA (-->), aMagmaLaneB (-->), aHeartLaneB (<-?->)
        //
        // Cross:
        //      aFuseLaneB (<--), aKeyRowReadB (<--), aFireLaneC (<--), aShadowLaneB (<-?->)
