            aIngress ^= (RotL64(aMagmaLaneB[((aIndex + 27224U)) & S_BLOCK1], 44U) ^ RotL64(aHeartLaneB[((S_BLOCK1 - aIndex + 25328U)) & S_BLOCK1], 27U));
