            aCross ^= (RotL64(aFireLaneC[((S_BLOCK1 - aIndex + 30118U)) & S_BLOCK1], 26U) ^ RotL64(aShadowLaneB[((S_BLOCK1 - aIndex + 27097U)) & S_BLOCK1], 43U));
