            //
            aOrbiterC = ((aWandererH + RotL64(aPrevious, 14U)) + RotL64(aCarry, 51U)) + 0xED660710937AA529ULL;
            aOrbiterJ = ((aWandererA + RotL64(aCross, 37U)) + 0x080EF064E07E1A77ULL) + aKeyRotateAOrbiterAssignSaltF[((aIndex + 18U)) & S_SALT1];
            aOrbiterG = (aWandererE + RotL64(aScatter, 3U)) + 0x6E88CC4365AD1D78ULL;
            aOrbiterK = ((aWandererF + RotL64(aIngress, 23U)) + RotL64(aCarry, 39U)) + 0x9D3CD5A942DE3A69ULL;
            aOrbiterH = ((aWandererK + RotL64(aCross, 51U)) + RotL64(aCarry, 11U)) + 0xD01F25B5D6FB9650ULL;
            aOrbiterD = (aWandererI + RotL64(aScatter, 29U)) + 0x9E7AD15E0C3979A0ULL;
            aOrbiterI = ((aWandererB + RotL64(aIngress, 43U)) + 0x878C26E4A9375B43ULL) + aKeyRotateAOrbiterAssignSaltA[(((31U - aIndex) + 15U)) & S_SALT1];
            //
            aOrbiterC = ((aOrbiterC + aOrbiterJ) + 0xC39188A9BA576551ULL) + aKeyRotateAOrbiterUpdateSaltF[(((31U - aIndex) + 24U)) & S_SALT1];
