            //
            aOrbiterH = ((aOrbiterH + aOrbiterD) + 0xF8EAB9BA69415C43ULL) + aKeyRotateAOrbiterUpdateSaltE[(((31U - aIndex) + 13U)) & S_SALT1];
            aOrbiterC = ((aOrbiterC ^ aOrbiterH) ^ 0x462FD183A09C7BE4ULL) ^ aKeyRotateAOrbiterUpdateSaltD[(((31U - aIndex) + 7U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0x181B2366195D52D9ULL), 11U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterC) + 0xA68BA6842CC81B63ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterD) ^ 0x7EDCEB3111D31A1DULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x9F1E49F991DA42B7ULL), 27U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterI) + 0xCD5E5B951E3E4853ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterK) ^ 0x5A0DD2FD88C873E8ULL;
