            //
            aOrbiterI = (aOrbiterI + aOrbiterH) + 0xBC4D1434C30A2041ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterI) ^ 0xEDAA9B3B06CFC7EBULL;
