            aWandererB = aWandererB ^ (((RotL64(aPrevious, 41U) + aOrbiterG) + RotL64(aOrbiterI, 19U)) + aKeyRotateAWandererUpdateSaltC[((aIndex + 25U)) & S_SALT1]);
            aWandererF = aWandererF + ((RotL64(aIngress, 3U) + aOrbiterK) + RotL64(aOrbiterD, 39U));
            aWandererH = aWandererH ^ (((RotL64(aScatter, 35U) + RotL64(aOrbiterH, 53U)) + aOrbiterK) + aKeyRotateAWandererUpdateSaltE[((aIndex + 23U)) & S_SALT1]);
            aWandererK = aWandererK + (((RotL64(aPrevious, 47U) + RotL64(aOrbiterD, 3U)) + aOrbiterI) + RotL64(aCarry, 57U));
